update herco_private.services set enabled=true,price_centavos=179900,label='Ceramic coating · TEST prices' where code='ceramic' and not enabled and price_centavos=0;
update herco_private.services set enabled=true,price_centavos=219900,label='Powder coating · TEST prices' where code='wheel-colour' and not enabled and price_centavos=0;
do $$ declare owner_id uuid; begin -- Attribute fixture entries to the shop's enabled Owner (exactly one is expected in the test project).
