end $$;
notify pgrst,'reload schema';
commit;
select 'UI TEST FIXTURE' as data_kind,(select count(*) from auth.users where id::text like 'f17e0000-%') as non_login_customers,(select count(*) from public.herco_bookings where id::text like 'f17e0000-%') as bookings,(select count(*) from herco_private.point_rewards where id::text like 'f17e0000-%') as rewards,(select count(*) from herco_private.stock_items where id::text like 'f17e0000-%') as stock_items;
